using System;
using System.Globalization;

namespace Rustegon.Driver;

/// <summary>
/// A hybrid logical clock timestamp (data-model.md §2, type 0x09): wall time plus a logical
/// counter. Mostly generated by the server; JSON form <c>{"$ts":"&lt;wall&gt;.&lt;logical&gt;"}</c>.
/// </summary>
/// <param name="Wall">Wall component (u64).</param>
/// <param name="Logical">Logical component (u32).</param>
public readonly record struct RDocTimestamp(ulong Wall, uint Logical) : IComparable<RDocTimestamp>
{
    /// <summary>Orders by wall time, then logical counter.</summary>
    /// <param name="other">The other timestamp.</param>
    /// <returns>Negative, zero or positive.</returns>
    public int CompareTo(RDocTimestamp other)
    {
        int c = Wall.CompareTo(other.Wall);
        return c != 0 ? c : Logical.CompareTo(other.Logical);
    }

    /// <summary>The <c>wall.logical</c> text of the <c>$ts</c> wrapper.</summary>
    /// <returns>The text.</returns>
    public override string ToString() =>
        Wall.ToString(CultureInfo.InvariantCulture) + "." + Logical.ToString(CultureInfo.InvariantCulture);

    /// <summary>Ordering operator.</summary>
    /// <param name="left">Left operand.</param>
    /// <param name="right">Right operand.</param>
    /// <returns>Whether <paramref name="left"/> is earlier.</returns>
    public static bool operator <(RDocTimestamp left, RDocTimestamp right) => left.CompareTo(right) < 0;

    /// <summary>Ordering operator.</summary>
    /// <param name="left">Left operand.</param>
    /// <param name="right">Right operand.</param>
    /// <returns>Whether <paramref name="left"/> is earlier or equal.</returns>
    public static bool operator <=(RDocTimestamp left, RDocTimestamp right) => left.CompareTo(right) <= 0;

    /// <summary>Ordering operator.</summary>
    /// <param name="left">Left operand.</param>
    /// <param name="right">Right operand.</param>
    /// <returns>Whether <paramref name="left"/> is later.</returns>
    public static bool operator >(RDocTimestamp left, RDocTimestamp right) => left.CompareTo(right) > 0;

    /// <summary>Ordering operator.</summary>
    /// <param name="left">Left operand.</param>
    /// <param name="right">Right operand.</param>
    /// <returns>Whether <paramref name="left"/> is later or equal.</returns>
    public static bool operator >=(RDocTimestamp left, RDocTimestamp right) => left.CompareTo(right) >= 0;
}
